#include <stdio.h>
#include <string.h>

#define MAX_STACK 512   /* original limit is 0x1ff (511) */

int main(int argc, char **argv)
{
    /* No argument -> BALANCED */
    if (argc < 2) {
        puts("BALANCED");
        return 0;
    }

    const char *s = argv[1];
    char stack[MAX_STACK];
    int top = 0;               /* stack pointer */
    int balanced = 1;          /* assume balanced */

    for (size_t i = 0; i < strlen(s) && balanced; ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            if (top >= MAX_STACK) { /* overflow */
                balanced = 0;
                break;
            }
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) { /* nothing to match */
                balanced = 0;
                break;
            }
            char open = stack[--top];
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                balanced = 0;
                break;
            }
        } else {
            /* any other character makes it unbalanced */
            balanced = 0;
            break;
        }
    }

    if (balanced && top == 0)
        puts("BALANCED");
    else
        puts("UNBALANCED");

    return 0;
}
